   else if(stage==21){Check(NativeUI.Renderer.HasTitle("所在方／控制者")&&NativeUI.Renderer.HasTitle("目标玩家 LP"),"new-card action preserves basic editor choices");EditorBehaviour.ProbeSearch("青眼");stage=22;}
   else if(stage==22){Check(NativeUI.Renderer.ScrollbarsFit(),"independent list scrollbars remain 12 pixels wide");Check(NativeUI.Renderer.ProbeResultHover(false),"visible search rows hover while hidden rows below viewport cannot hover");EditorBehaviour.ProbeResultScroll(200);stage=220;}
   else if(stage==220){Check(NativeUI.Renderer.ProbeResultHover(true),"scrolled-off search rows above viewport cannot hover");EditorBehaviour.ProbeResultScroll(0);EditorBehaviour.ProbeSelect(89631139);EditorBehaviour.ProbeSearch("");EditorBehaviour.ProbeBottom();stage=23;}
   else if(stage==23){NativeUI.Renderer.Click("生成卡片");stage=24;}
   else if(stage==24){Check(s.Cards().Count(c=>c.Location==4)==1,"generate through real UI button");EditorBehaviour.ShowForSmoke();Check(MDPro3.Program.instance.ocgcore.GetUI<MDPro3.UI.ServantUI.OcgCoreUI>().CardDescription.showing,"native card preview visible after generation");Check(NativeUI.Renderer.ScrollbarsFit(),"editor scrollbar remains narrow after generation");stage=25;}
   else if(stage==25){Check(NativeUI.Renderer.HasTitle("所在方／控制者")&&NativeUI.Renderer.HasTitle("目标玩家 LP"),"generate keeps all editor options visible");Check(!MDPro3.Program.instance.ocgcore.greenOn,"editor input never enables solid-color background");EditorBehaviour.ProbePage(2);stage=26;}
   else if(stage==26){Check(NativeUI.Renderer.HasTitle("种族")&&NativeUI.Renderer.HasTitle("攻击力"),"original YGO shape window retains attribute and type placement");NativeUI.Renderer.Click("状态与限制");stage=27;}
   else if(stage==27){Check(EditorBehaviour.ProbeRestrictionGrid(),"filtered restriction options form balanced columns without empty slots");Check(NativeUI.Renderer.HasTitle("◆ 卡片被无效")||NativeUI.Renderer.HasTitle("◇ 卡片被无效"),"original restriction window retains two bounded columns");EditorBehaviour.ProbePage(3);stage=28;}
   else if(stage==28){Check(NativeUI.Renderer.HasTitle("立即洗牌")&&NativeUI.Renderer.HasTitle("置底"),"original deck order window retains list and movement controls");EditorBehaviour.ProbePage(4);stage=29;}
   else if(stage==29){Check(NativeUI.Renderer.HasTitle("新建文件夹")&&NativeUI.Renderer.HasTitle("读取选中时点"),"original save window retains folders and separate action buttons");EditorBehaviour.ShowForSmoke();stage=13;}
   else if(stage==13){File.WriteAllText(Path.Combine(BepInEx.Paths.PluginPath,"DuelStructure","widgets.txt"),NativeUI.Renderer.Describe());MDPro3.Program.instance.ocgcore.OnExit();stage=30;frame=Time.frameCount+180;return;}
   frame=Time.frameCount+120;
   }catch(Exception e){Plugin.Instance.Log.LogError(e);stage=-1;if(Host.Session!=null)Host.Session.Paused=true;}
  }
 }
